use genex::prelude::*;

/// Where the grip sits in camera space: right, up, forward, in metres.
const GRIP: Vec3 = Vec3::new(0.17, -0.19, 0.45);

/// Read-only after reset: the viewmodel's two models. Motion lives in the world (sway, bob, kick).
#[derive(Default)]
pub struct Viewmodel { arms: Model, gun: Model }

pub fn wire(game: &mut Game<super::World>) {
    game.facet_state::<Viewmodel>();
    game.on_reset(|sim, _seed, _rng, gfx| {
        let vm = sim.facets.get_mut::<Viewmodel>();
        vm.arms = gfx.assets().model("viewmodel/arms.glb"); // gloved forearms and hands, posed on the grip
        vm.gun = gfx.assets().model("viewmodel/pistol.glb");
    });
    game.on_update(|sim, ctx| {
        let w = &mut sim.world;
        // Lag: the gun trails the turn and settles back, so it hangs off a body, not the lens.
        w.sway = w.sway.lerp(ctx.look * -0.0005, 0.25);
        // Bob from the walking speed, never from the clock: standing still holds it still.
        w.bob_phase += w.walk_speed * ctx.dt * 1.7;
        w.kick = (w.kick - ctx.dt * 6.0).max(0.0);
    });
    // Drawn from the camera every frame: there is no parenting, the pose is camera space.
    game.on_draw(|sim, frame, camera| {
        let w = &sim.world;
        let vm = sim.facets.get::<Viewmodel>();
        let bob = vec3(genex::math::sin(w.bob_phase) * 0.008, -genex::math::sin(w.bob_phase * 2.0).abs() * 0.006, 0.0);
        let local = GRIP + vec3(w.sway.x, w.sway.y, -w.kick * 0.06) + bob;
        // The player's own yaw and pitch, the ones its camera hook looks along.
        let pose = viewmodel_pose(camera.position, w.yaw, w.pitch + w.kick * 0.25, local);
        frame.tag("hands").id(1u64).model(&vm.arms, pose).end_id();
        frame.tag("weapon").id(2u64).model(&vm.gun, pose).end_id();
    });
}

/// A camera-space offset (x right, y up, z forward) as a world transform, turned by the view's yaw and pitch.
fn viewmodel_pose(eye: Vec3, yaw: f32, pitch: f32, local: Vec3) -> Transform {
    let turn = Quat::from_rotation_y(yaw) * Quat::from_rotation_x(pitch);
    let at = eye + turn * vec3(local.x, local.y, -local.z); // at yaw 0 the view looks down -Z, +X to its right
    Transform::from_translation(at).with_rotation(turn)
}
